<script setup lang="ts">
import { computed, reactive, ref } from "vue"; import { useRouter } from "vue-router";
import AppShell from "@/components/zs/AppShell.vue"; import PageHeader from "@/components/zs/PageHeader.vue"; import Panel from "@/components/zs/Panel.vue"; import DataTable from "@/components/zs/DataTable.vue"; import Toolbar from "@/components/zs/Toolbar.vue"; import SearchInput from "@/components/zs/SearchInput.vue"; import StatusBadge from "@/components/zs/StatusBadge.vue"; import UserAvatar from "@/components/crm/UserAvatar.vue"; import Pagination from "@/components/crm/Pagination.vue"; import SidePanel from "@/components/zs/SidePanel.vue"; import Field from "@/components/zs/Field.vue"; import ZButton from "@/components/zs/ZButton.vue"; import AsyncSection from "@/components/zs/AsyncSection.vue"; import ValidationMessage from "@/components/zs/ValidationMessage.vue";
import { useCrmData } from "@/composables/useCrmData"; import { useAsyncData,useMutation } from "@/composables/useAsyncData"; import { crmRepository } from "@/services/crm/repository"; import type { CrmContact } from "@/types/crm"; import { showToast } from "@/composables/useToast"; import { setPageMeta } from "@/lib/page-meta";
setPageMeta("Contacts","People and decision makers across CRM accounts.");const data=useCrmData(),router=useRouter(),search=ref(""),status=ref("All statuses"),page=ref(1),open=ref(false),editingId=ref<string|null>(null);const listing=useAsyncData(()=>crmRepository.contactsPage(data.activeCompanyId.value,{search:search.value,status:status.value==="All statuses"?undefined:status.value,page:page.value,per_page:10}),{watch:[data.activeCompanyId,search,status,page]});const rows=computed(()=>listing.data.value?.data??[]);
const form=reactive({first_name:"",last_name:"",account_id:"",job_title:"",department:"",email:"",phone:"",mobile:"",owner_id:"",status:"ACTIVE",is_primary:false,notes:""});const columns=[{key:"name",header:"Name"},{key:"company",header:"Company"},{key:"title",header:"Job title"},{key:"email",header:"Email"},{key:"phone",header:"Phone"},{key:"owner",header:"Owner"},{key:"status",header:"Status"},{key:"lastActivity",header:"Last activity"},{key:"actions",header:"",align:"right" as const}];
function edit(item?:CrmContact){editingId.value=item?.id??null;Object.assign(form,{first_name:item?.firstName??"",last_name:item?.lastName??"",account_id:item?.accountId??"",job_title:item?.title??"",department:item?.department??"",email:item?.email??"",phone:item?.phone??"",mobile:item?.mobile??"",owner_id:item?.ownerId?String(item.ownerId):"",status:item?.status??"ACTIVE",is_primary:item?.isPrimary??false,notes:item?.notes??""});open.value=true;}
const mutation=useMutation(()=>{const input={...form,account_id:form.account_id||null,owner_id:form.owner_id?Number(form.owner_id):null};return editingId.value?crmRepository.updateContact(data.activeCompanyId.value,editingId.value,input):crmRepository.createContact(data.activeCompanyId.value,input)});async function save(){const saved=await mutation.run();if(!saved)return;open.value=false;await Promise.all([listing.refresh(),data.contacts.refresh(),data.companies.refresh()]);showToast("Contact saved",`${saved.name} is up to date.`,"success");}
</script>
<template><AppShell><PageHeader title="Contacts" :description="`${listing.data.value?.total??0} people across client accounts`"><template #actions><ZButton @click="edit()">Add contact</ZButton></template></PageHeader><Panel><Toolbar><SearchInput v-model="search" placeholder="Search contact, company, email or phone"/><select v-model="status" class="field max-w-40"><option>All statuses</option><option>ACTIVE</option><option>INACTIVE</option></select></Toolbar><AsyncSection :loading="listing.loading.value" :error="listing.error.value" :empty="listing.data.value?.total===0" @retry="listing.refresh"><DataTable :columns="columns" :rows="rows" :min-width="1200"><template #name="{row}"><button class="flex items-center gap-2 font-medium text-content" @click="router.push(`/crm/contacts/${row.id}`)"><UserAvatar :name="row.name"/>{{row.name}}</button></template><template #status="{row}"><StatusBadge :status="row.status"/></template><template #actions="{row}"><ZButton variant="ghost" @click="router.push(`/crm/contacts/${row.id}`)">View</ZButton><ZButton variant="ghost" @click="edit(row)">Edit</ZButton></template><template #footer><Pagination :page="listing.data.value?.currentPage??1" :pages="listing.data.value?.lastPage??1" :total="listing.data.value?.total??0" @change="page=$event"/></template></DataTable></AsyncSection></Panel><SidePanel :open="open" :title="editingId?'Edit contact':'Add contact'" @close="open=false"><form class="grid gap-4 sm:grid-cols-2" @submit.prevent="save"><Field v-model="form.first_name" label="First name" required/><Field v-model="form.last_name" label="Last name"/><label class="sm:col-span-2"><span class="label-caps">Company</span><select v-model="form.account_id" class="field mt-1.5"><option value="">No linked company</option><option v-for="company in data.companies.data.value??[]" :key="company.id" :value="company.id">{{company.name}}</option></select></label><Field v-model="form.job_title" label="Job title"/><Field v-model="form.department" label="Department"/><Field v-model="form.email" label="Email" type="email"/><Field v-model="form.phone" label="Phone"/><label><span class="label-caps">Owner</span><select v-model="form.owner_id" class="field mt-1.5"><option value="">Unassigned</option><option v-for="owner in data.owners.data.value??[]" :key="owner.id" :value="owner.id">{{owner.name}}</option></select></label><label><span class="label-caps">Status</span><select v-model="form.status" class="field mt-1.5"><option>ACTIVE</option><option>INACTIVE</option></select></label><label class="flex items-center gap-2 text-xs"><input v-model="form.is_primary" type="checkbox"/> Primary contact</label><ValidationMessage class="sm:col-span-2" :message="mutation.error.value?.message"/><ZButton type="submit" :disabled="mutation.saving.value">Save contact</ZButton></form></SidePanel></AppShell></template>
